suppressPackageStartupMessages({library(data.table);library(GenomicRanges);library(jsonlite);library(ggplot2)})
set.seed(260925);out='output/followup_analysis/'
savep=function(x,n,w=11,h=6){for(e in c('png','pdf'))ggsave(paste0(out,'figures/',n,'.',e),x,width=w,height=h,dpi=220)}
a=fread('data/results/peak_analysis/figures/all_nonzero_peaks/transcript_region_bias/peak_transcript_region_annotations.tsv');pg=GRanges(a$summit_chromosome,IRanges(a$summit_start_0based+1,width=1),a$summit_strand)
f=fread('data/results_round2/features.tsv.gz');f=f[kind%in%c('intron','3UTR') & length_nt>=100];ss=lapply(f$segments_0based_half_open,fromJSON);sg=rbindlist(lapply(seq_along(ss),function(i){m=ss[[i]];data.table(fi=i,chrom=f$chrom[i],strand=f$strand[i],start=m[,1],end=m[,2],cum=c(0,head(cumsum(m[,2]-m[,1]),-1)))}));gr=GRanges(sg$chrom,IRanges(sg$start+1,sg$end),sg$strand)
h=suppressWarnings(findOverlaps(pg,gr));hits=data.table(pi=queryHits(h),si=subjectHits(h));hits[,fi:=sg$fi[si]];hits[,`:=`(kind=f$kind[fi],length=f$length_nt[fi])];setorder(hits,kind,pi,-length,fi);hits=hits[!duplicated(paste(kind,pi))];hits[,offset:=sg$cum[si]+a$summit_start_0based[pi]-sg$start[si]];hits[f$strand[fi]=='-',offset:=length-1-offset];hits[,`:=`(fraction=(offset+.5)/length,peak_id=a$peak_id[pi],feature_id=f$feature_id[fi])]
# Same coordinate-only peak can contribute to intron and UTR in different transcript models; each analysis separately chooses one longest model.
hits[,quartile:=findInterval(length,quantile(f[kind=='intron',length_nt],c(.25,.5,.75)))+1L]
hits[,sites_in_feature:=.N,by=.(kind,feature_id)]
fwrite(hits,paste0(out,'tables/summit_normalized_positions.tsv.gz'),sep='\t')
allprof=list();allzones=list();summary=list()
for(k in c('intron','3UTR')){
 z=hits[kind==k];n=nrow(z);b=pmin(99L,floor(z$fraction*100));obs=tabulate(b+1L,100)/n
 null=matrix(0,100,500);hist=matrix(0,100,500);zone=matrix(0,4,500);zoneh=zone
 for(it in 1:500){r=floor(runif(n)*z$length);u=(r+.5)/z$length;null[,it]=tabulate(floor(u*100)+1L,100)/n;zone[,it]=c(mean(u<.1),mean(u>=.1&u<.9),mean(u>=.9),mean(z$length-r<=100));
 # PARpipe Spatial.R plotSample func: sample((25/2):(n-25/2),1). Reproduce half-integer 1-nt grid, not continuous runif.
 rp=12.5+floor(runif(n)*(floor(z$length-25)+1));up=rp/z$length;hist[,it]=tabulate(pmin(100L,floor(up*100)+1L),100)/n;zoneh[,it]=c(mean(up<.1),mean(up>=.1&up<.9),mean(up>=.9),mean(z$length-rp<=100))}
 prof=data.table(kind=k,bin=0:99,position=(0:99+.5),observed=obs,null_median=apply(null,1,median),null_low=apply(null,1,quantile,.025),null_high=apply(null,1,quantile,.975),PARpipe_median=apply(hist,1,median),PARpipe_low=apply(hist,1,quantile,.025),PARpipe_high=apply(hist,1,quantile,.975),N=n,eligible_features=sum(f$kind==k),supported_features=uniqueN(z$feature_id),permutations=500,seed=260925)
 allprof[[k]]=prof;oz=c(mean(z$fraction<.1),mean(z$fraction>=.1&z$fraction<.9),mean(z$fraction>=.9),mean(z$length-z$offset<=100))
 allzones[[k]]=rbindlist(lapply(c('within_model_uniform','PARpipe_25nt_margin'),function(method){nm=if(method=='within_model_uniform')zone else zoneh;data.table(kind=k,method=method,zone=c('first10','middle80','last10','last100nt'),observed_fraction=oz,expected_fraction=rowMeans(nm),enrichment=oz/rowMeans(nm),null_low=apply(nm,1,quantile,.025),null_high=apply(nm,1,quantile,.975),empirical_p=(1+rowSums(nm>=oz))/501,N=n)}))
 saveRDS(list(modern=null,PARpipe=hist,zone_modern=zone,zone_PARpipe=zoneh),paste0(out,'cache/',k,'_spatial_nulls.rds'))
}
prof=rbindlist(allprof);fwrite(prof,paste0(out,'tables/summit_spatial_profiles.tsv'),sep='\t');zz=rbindlist(allzones);zz[,q_BH:=p.adjust(empirical_p,'BH')];fwrite(zz,paste0(out,'tables/summit_spatial_zone_tests.tsv'),sep='\t')
savep(ggplot(prof,aes(position,observed))+geom_ribbon(aes(ymin=null_low,ymax=null_high),fill='grey80')+geom_line(aes(y=null_median),color='grey40',lty=2)+geom_line(color='#236d83')+facet_wrap(~kind)+theme_bw()+labs(x='Feature position (%)',y='Fraction of assigned summits per1% bin',title='MSI2 reference summits versus within-feature background',subtitle='One longest matching model per summit per feature type; 500 permutations'),'summit_spatial_background')
savep(ggplot(prof[kind=='3UTR'],aes(position,observed))+geom_ribbon(aes(ymin=PARpipe_low,ymax=PARpipe_high),fill='#ecddc0')+geom_line(aes(y=PARpipe_median),color='#b17a27',lty=2)+geom_line(color='#236d83')+theme_bw()+labs(x="3′UTR position (%)",y='Fraction of summits per1% bin',title='Historical PARpipe background sensitivity',subtitle='Exact 25-nt implicit footprint margin; hg38 GENCODEv26 models; 500 draws'),'PARpipe_UTR_background')
z=hits[kind=='intron'];z[,bin:=floor(fraction*100)];iv=z[,.(site_count=.N,intron_weight=sum(1/sites_in_feature)),by=.(quartile,bin)];den=z[,.(sites=.N,bound_introns=uniqueN(feature_id)),by=quartile];iv=merge(iv,den,by='quartile');iv[,`:=`(site_weighted=site_count/sites,intron_weighted=intron_weight/bound_introns)];fwrite(iv,paste0(out,'tables/metaintron_peak_quartiles.tsv'),sep='\t');iv=melt(iv,id.vars=c('quartile','bin'),measure.vars=c('site_weighted','intron_weighted'));savep(ggplot(iv,aes(bin+.5,value,color=variable))+geom_line()+facet_wrap(~quartile)+theme_bw()+labs(x='Intron position (%)',y='Fraction per1% bin',title='Intron summit density: length quartiles and weighting'),'metaintron_site_weighting')
# Secondary construct labels come from continuous fixed-universe scores; not endogenous construct labels.
dd=fread(paste0(out,'raw_count_quantile/continuous_delta_delta_peaks.tsv'));sec=merge(hits,dd[,.(peak_id,delta_delta)],by='peak_id');sec[,construct_preference:=ifelse(delta_delta>0,'324','328')];sec[,bin:=floor(fraction*100)];s=sec[,.(sites=.N),by=.(kind,construct_preference,bin)];s[,fraction:=sites/sum(sites),by=.(kind,construct_preference)];fwrite(s,paste0(out,'tables/construct_associated_summit_profiles.tsv'),sep='\t');savep(ggplot(s,aes(bin+.5,fraction,color=construct_preference))+geom_line()+facet_wrap(~kind)+theme_bw()+labs(x='Feature position (%)',y='Fraction of sign-selected summits',title='Secondary: construct-associated sites in the fixed counted universe'),'construct_summit_spatial')
